BASE = dict(stage="M1", introduced_by="M1.1", last_changed_by="M1.1")
DRAFT_MAP = "litepaper-baseline-map.md"
DRAFT_GE = "growth-and-entry-assessment.md"
DRAFT_VD = "validator-decision-map.csv"
DRAFT_EX = "experiments/m1/baseline-accounting"


def rec(rid, rt, caption, **f):
    t = {"title": rid, "record_type": rt, "caption": caption, "tags": "FX" if rt == "FX" else f"Record {rt}", **BASE}
    for k, v in f.items():
        if v not in (None, ""):
            t[k] = v
    R.append(t)


def src(lines):
    return f"SRC-LP20 {lines}"


