# ================================================================== pilot filter
if "--pilot" in sys.argv:
    PILOT_LP = {"LP-03", "LP-04", "LP-07"}
    keep = set()
    for r in R:
        cs = set(r.get("concepts", "").split())
        if r["title"] in PILOT_LP or (cs & PILOT_LP):
            keep.add(r["title"])
    # close over references so the pilot has no dangling links
    changed = True
    while changed:
        changed = False
        for r in R:
            if r["title"] in keep:
                for fld in ("concepts", "provisions", "conflicting_provisions", "decisions", "claims", "findings",
                            "scenarios", "pair_with", "experiments", "components", "related"):
                    for ref in r.get(fld, "").split():
                        if ref not in keep:
                            keep.add(ref); changed = True
    R = [r for r in R if r["title"] in keep]

json.dump(R, sys.stdout, indent=1, ensure_ascii=False)
